import { createHash } from 'node:crypto';
import { json } from '@appdeploy/sdk';
import { BRAND } from '../shared/brand-release';

let checkedAt = 0;
let assetAvailable = false;
let assetStatus = 'AWAITING_RESOURCES_UPLOAD';
export const brandReleaseRoutes = {
  'GET /api/brand-release': [async () => {
    if (Date.now() - checkedAt > 15000) {
      assetAvailable = false; assetStatus = 'AWAITING_RESOURCES_UPLOAD';
      try {
        const response = await fetch(BRAND.origin + BRAND.assetUrl, { redirect: 'error', signal: AbortSignal.timeout(3500) });
        if (response.ok && (response.headers.get('content-type') || '').startsWith('image/')) {
          const bytes = new Uint8Array(await response.arrayBuffer());
          if (bytes.byteLength <= 2_000_000) {
            assetAvailable = createHash('sha256').update(bytes).digest('hex') === BRAND.assetSha256;
            assetStatus = assetAvailable ? 'VERIFIED' : 'HASH_MISMATCH';
          } else assetStatus = 'RESOURCE_TOO_LARGE';
        }
      } catch { assetAvailable = false; assetStatus = 'RESOURCE_NOT_VERIFIED'; }
      checkedAt = Date.now();
    }
    return json({ brand: BRAND, assetAvailable, assetStatus, actionsExecuteTransactions: false });
  }],
};

/* Ross PDF brand integration. Documentation remains documentation. */
:root { --ross-brand-navy: #0B2D5B; --ross-brand-gold: #D4AF37; --ross-brand-silver: #C0C0C0; --ross-brand-cream: #F8F4E9; --ross-brand-black: #0A0A0A; }
.ross-release-native { display: contents; }
.ross-release-native[hidden] { display: none !important; }
.ross-release-page { box-sizing: border-box; width: auto; min-height: 65vh; font: 16px/1.6 'Montserrat', system-ui, sans-serif; }
.ross-release-page h1, .ross-release-page h2 { font-family: 'Playfair Display', Georgia, serif; color: var(--ross-brand-navy); }
.ross-release-page code { overflow-wrap: anywhere; white-space: normal; }
.ross-release-page button { padding: 10px 16px; border: 1px solid var(--ross-brand-gold); border-radius: 7px; background: var(--ross-brand-navy); color: var(--ross-brand-cream); cursor: pointer; }
.ross-release-page button:disabled { opacity: .6; cursor: not-allowed; }
.ross-release-page :focus-visible { outline: 3px solid var(--ross-brand-gold); outline-offset: 3px; }
@media (max-width: 560px) { .ross-release-page { padding: 20px 14px !important; } }
